                intent.setType("image/");
                startActivityForResult(Intent.createChooser(intent, "Select Picture"), 1);
            }
        });


        SharedPreferences sharedPreferences = getActivity().getSharedPreferences("myPrefs_profile", Context.MODE_PRIVATE);
