```
private void saveImageToStorage(Bitmap bitmap) {
    try {
        File storageDir = getActivity().getExternalFilesDir(Environment.DIRECTORY_PICTURES);
        File imageFile = File.createTempFile(
                "profile_picture_", ".jpg",
        storageDir); // создаем временный файл изображения

        FileOutputStream out = new FileOutputStream(imageFile);
        bitmap.compress(Bitmap.CompressFormat.JPEG, 100, out);
        out.flush();
        out.close();

        SharedPreferences sharedPreferences = getActivity().getSharedPreferences("myPrefs_profile", Context.MODE_PRIVATE);
        SharedPreferences.Editor editor = sharedPreferences.edit();
        editor.putString("profile_picture_path", imageFile.getAbsolutePath()); // сохраняем путь к файлу в SharedPreferences
        editor.apply();

        BitmapFactory.Options options = new BitmapFactory.Options();
        options.inSampleSize = 2; // уменьшаем размер изображения для ускорения работы
        Bitmap scaledBitmap = BitmapFactory.decodeFile(imageFile.getAbsolutePath(), options);
        Bitmap circleBitmap = Bitmap.createBitmap(scaledBitmap.getWidth(), scaledBitmap.getHeight(), Bitmap.Config.ARGB_8888);
        BitmapShader shader = new BitmapShader(scaledBitmap, BitmapShader.TileMode.CLAMP, BitmapShader.TileMode.CLAMP);
        Paint paint = new Paint();
        paint.setShader(shader);
        Canvas c = new Canvas(circleBitmap);
        c.drawCircle(scaledBitmap.getWidth()/2, scaledBitmap.getHeight()/2, scaledBitmap.getWidth()/2, paint);

        ImageView imageViewProfile = getView().findViewById(R.id.imageButtonProfile);
        imageViewProfile.setImageBitmap(circleBitmap);

    } catch (IOException e) {
        e.printStackTrace();
    }
} 
