using System.Data.OleDb;
using System.Drawing;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Windows.Forms;
using static System.Windows.Forms.VisualStyles.VisualStyleElement.Button;


namespace DForm1
{
    public partial class RegForm : Form
    {
        public RegForm()
        {
            InitializeComponent();
        }
        OleDbConnection con = new OleDbConnection("Provider=Microsoft.Jet.OLEDB.4.0;Data Source=db_users.mdb");
        OleDbCommand cmd = new OleDbCommand();
        OleDbDataAdapter da = new OleDbDataAdapter();              //Connection to Database


        private void txtUsername_TextChanged(object sender, EventArgs e)
        {

        }

        private void btnRegister_Click(object sender, EventArgs e) 
        {
            string password = txtPassword.Text;
            string confirmPassword = txtConfirmPassword.Text;
            string username = txtUsername.Text;

            if (string.IsNullOrEmpty(username) || string.IsNullOrEmpty(password))
            {
                MessageBox.Show("Please enter a username and password.");
                return;
            }
            else if (!Regex.IsMatch(username, "^[a-zA-Z0-9]*$"))
            {
                MessageBox.Show("Username must only contain letters and numbers.");
            }
            else if (username.Length > 20)
            {
                MessageBox.Show("Username is too long. Maximum 20 characters.");
                return;
            }
            else if (password.Length < 8 || password.Length > 16)
            {
                MessageBox.Show("Password must be between 8 and 16 characters.");
                return;
            }
            else if (!password.Any(char.IsLower) || !password.Any(char.IsUpper))
            {
                MessageBox.Show("Password must contain at least one lowercase and one uppercase letter.");
                return;
            }
            else if (password != confirmPassword)
            {
                MessageBox.Show("Passwords do not match. Please try again.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }
            else if (!Regex.IsMatch(txtEmail.Text, @"^[^@\s]+@[^@\s]+\.[^@\s]+$"))            
            {
                MessageBox.Show("Please enter a valid email address.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;                                           //Validation to Register
            }                                                                   
            else
            {
                con.Open();
                string register = "INSERT INTO tbl_users VALUES ('" + txtUsername.Text + "','" + txtPassword.Text + "','" + txtEmail.Text + "','" + txtPhoneNumber.Text + "','" + txtSurname.Text + "','" + txtForename.Text + "')";
                cmd = new OleDbCommand(register, con);
                cmd.ExecuteNonQuery();
                con.Close();
                MessageBox.Show("Registration successful.");
                this.Hide();
                LoginForm loginForm = new LoginForm();
                loginForm.Show();                                         //Login Form
            }
        }







