using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Data.OleDb;
using System.Drawing;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;
using static System.Windows.Forms.VisualStyles.VisualStyleElement;

namespace DForm1
{
    public partial class CustomerForm : Form
    {
        private OleDbConnection connection;
        private OleDbDataAdapter adapter;
        private DataSet dataSet;
        private DataTable dataTable;
        private DataView dataView;
        public CustomerForm()
        {
            InitializeComponent();

        }

        private void dataGridView1_CellContentClick(object sender, DataGridViewCellEventArgs e)
        {

        }

        private void UserForm_Load(object sender, EventArgs e)
        {
            connection = new OleDbConnection("Provider=Microsoft.ACE.OLEDB.12.0;Data Source=db_appliances.mdb");
            adapter = new OleDbDataAdapter("SELECT * FROM tbl_appliances", connection);
            dataSet = new DataSet();
            adapter.Fill(dataSet, "tbl_appliances");
            dataTable = dataSet.Tables["tbl_appliances"];
            dataView = new DataView(dataTable);
            dataGridView1.DataSource = dataView;
            dataGridView2.CellContentClick += dataGridView2_CellContentClick;
                                                                              //Connection to Database and Table with Data
        }







        private void button1_Click(object sender, EventArgs e)
            {
            DataGridViewRow newRow = new DataGridViewRow();
            newRow.CreateCells(dataGridView2);
            newRow.Cells[0].Value = dataGridView1.SelectedRows[0].Cells[0].Value.ToString();
            newRow.Cells[1].Value = dataGridView1.SelectedRows[0].Cells[1].Value.ToString();
            newRow.Cells[2].Value = dataGridView1.SelectedRows[0].Cells[2].Value.ToString();
            newRow.Cells[3].Value = dataGridView1.SelectedRows[0].Cells[3].Value.ToString();
            dataGridView2.Rows.Add(newRow);


            double totalPrice = 0;
            foreach (DataGridViewRow row in dataGridView2.Rows)
            {
                double price = Convert.ToDouble(row.Cells[3].Value);
                totalPrice += price;                                                      // Adding To Cart
            } 


            txtTotalPrice.Text = "£" + totalPrice.ToString("#,##0.00");
        }















        private void radioButton1_CheckedChanged(object sender, EventArgs e)
        {
            {
                if (radioButton1.Checked)
                {


                    DataView dv = dataTable.DefaultView;
                    dv.Sort = "Power Usage";
                    dataGridView1.DataSource = dv;                                //Sorting by Power Usage
                }
            }
        }

        private void radioButton2_CheckedChanged(object sender, EventArgs e)
        {


            DataView dv = dataTable.DefaultView;
            dv.Sort = "Estimated annual running costs"; 
            dataGridView1.DataSource = dv.ToTable();                               //Sorting by Cost


        }

        private void dataGridView2_CellContentClick(object sender, DataGridViewCellEventArgs e)
        {
            double totalPrice = 0;
            foreach (DataGridViewRow row in dataGridView2.Rows)
            {
                double price = Convert.ToDouble(row.Cells[3].Value);
                totalPrice += price;
            }

                                                                                   //Calculation of Total price
            txtTotalPrice.Text = totalPrice.ToString();
        }

        private void txtTotalPrice_TextChanged(object sender, EventArgs e)
        {

        }

        private void button3_Click(object sender, EventArgs e)
        {
            if (dataGridView2.SelectedRows.Count > 0)
            {
                int rowIndex = dataGridView2.SelectedRows[0].Index;
                dataGridView2.Rows.RemoveAt(rowIndex);

                // Recalculate total price
                double totalPrice = 0;
                foreach (DataGridViewRow row in dataGridView2.Rows)
                {
                    double price = Convert.ToDouble(row.Cells[3].Value);
                    totalPrice += price;
                }                                                                      //Removing From Cart
                txtTotalPrice.Text = "£" + totalPrice.ToString("#,##0.00");
            }
        }

