CSS:
html, body, h1, h2, h3, h4, p, a, ul, li, div, main, header, section, footer, img {
  margin: 0;
  padding: 0;
  border: 0;
  font-size: 100%;
  font-family: inherit;
  vertical-align: baseline;
  box-sizing: border-box;
}

body {
  font-family: "Cabin", sans-serif;
  line-height: 1.5;
  color: #333;
  width: 100%;
  margin: 0;
  padding: 0;
  min-height: 100vh;
  flex-direction: column;
  display: flex;
  background-image: url("../assets/images/cover.jpg");
  background-size: cover;
}
header {
  background: #00000000;
  padding: 0.5rem 2rem;
  text-align: center;
  color: #32612D;
  font-size: 1.2rem;
}
main{
  flex-grow: 1;
}

.sticky-nav {
  position: -webkit-sticky;
  position: sticky;
  top: 0;
  z-index: 1000;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
}
.search-container {
   display: inline-block;
   position: relative;
}

.search-container input[type="text"] {
padding: 0.8rem;
border: none;
border-bottom: 1.5px solid #32612D;
outline: none;
color: #32612D;
font-size: 1rem;
background-color: transparent;
margin-right: 30rem;
margin-bottom: 12px;
width: 65%;
}

.search-container input[type="text"]::placeholder {
color: #32612D;
opacity: 0.5;
}
.search-icon {
  margin-right: 0.8rem;
  width: 24px;
  height: auto;
  vertical-align: middle;
  position: absolute;
  top: 50%;
  margin-top: -16px; 

}


.search-container input[type="text"]:focus {
border-color: #ADC3AB;
}

.search-container button[type="submit"] {
display: none;
}
.logo {
  width: 50px;
  height: auto;
  margin-right: 1rem;
}

h1 {
  flex-grow: 1;
  text-align: left;
}

nav ul {
  display: inline


  list-style: none;
}

nav ul li {
  display: inline;
  margin-left: 1rem;
}

nav ul li a {
  text-decoration: none;
  color: #32612D;
  position: relative;
  transition: color 0.3s ease;
}

@media screen and (max-width: 768px) {
  .nav-container {
    flex-direction: column;
  }
  h1 {
    margin-bottom: 1rem;
  }
}
nav ul li a {
  text-decoration: none;
  color: #32612D;
  position: relative;
  transition: color 0.3s ease;
}


nav ul li a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: #000;
  transform: scaleX(0);
  transition: transform 0.3s;
}
nav ul li a:hover {
  color: #000000;
}
nav ul li a:hover::after {
  transform: scaleX(1);
}

.slideshow-container {
width: 100%;
position: relative;
margin: 1rem 0;
}

.mySlides {
display: none;
}

.mySlides img {
width: 100%;
height: auto;
}

/* Slideshow navigation */
.prev, .next {
  cursor: pointer;
  position: absolute;
  top: 50%;
  width: auto;
  margin-top: -22px;
  padding: 16px;
  color: #32612D;
  font-weight: bold;
  font-size: 18px;
  transition: 0.6s ease;
  border-radius: 0 3px 3px 0;
  user-select: none;
}

.next {
  right: 0;
  border-radius: 3px 0 0 3px;
}

.prev:hover, .next:hover {
  background-color: rgba(255,255,255,0.8);
}

.dot {
  cursor: pointer;
  height: 15px;
  width: 15px;
  margin: 0 2px;
  background-color: #bbb;
  border-radius: 50%;
  display: inline-block;
  transition: background-color 0.6s ease;
}

.dot:hover {
  background-color: #717171;
}

.fade {
  -webkit-animation-name: fade;
  -webkit-animation-duration: 1.5s;
  animation-name: fade;
  animation-duration: 1.5s;
}

@-webkit-keyframes fade {
  from {opacity: .4}
  to {opacity: 1}
}

@keyframes fade {
  from {opacity: .4}
  to {opacity: 1}
}

.about-section {

  padding: 1rem;
  text-align: center;
  margin: 1rem 0;
}

.featured-section {

  padding: 1rem;
  text-align: center;
  margin: 1rem 0;
}

.featured-section h2 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.featured-container {
  display: flex;
  justify-content: space-around;
  align-items: center;
  flex-wrap: wrap;
  margin: 1rem 0;
}

.featured-product {
  width: 150px;
  padding: 1rem;
  background-color: #ADC3AB;
  border-radius: 5px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  transition: all 0.3s ease;
  margin: 0.5rem;
}

.featured-product:hover {
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
  transform: translateY(-5px);
}

.featured-product img {
  width: 100%;
  height: auto;
  margin-bottom: 1rem;
  border-radius: 5px;
}

.special-offers-container {
display: flex;
justify-content: space-around;
align-items: center;
flex-wrap: wrap;
margin: 1rem 0;
}

.special-offer {
width: 200px;
padding: 1rem;
text-align: center;
margin: 1rem;
background-color: #ADC3AB;
border-radius: 5px;
box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
transition: all 0.3s ease;
}

.special-offer:hover {
box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
transform: translateY(-5px);
}

.special-offer img {
width: 100%;
height: auto;
margin-bottom: 0.5rem;
border-radius: 5px;
}

.modal {
display: none;
position: fixed;
left: 0;
top: 0;
width: 100%;
height: 100%;
background-color: rgba(0, 0, 0, 0.5);
z-index: 1;
overflow: auto;
align-items: center;
}

.modal-content {
background-color: #fefefe;
padding: 2rem;
margin: 10% auto;
width: 30%;
min-width: 300px;
max-width: 80%;
text-align: center;
border-radius: 5px;
box-shadow: 0 1px 8px rgba(0, 0, 0, 0.1);
}
.modalBtn{
  background-color: #ADC3AB;
   color: #32612D;
   padding: 0.5rem;
   border: none;
   border-radius: 5px;
   cursor: pointer;
}

.buts {

text-align: center;

}
.footer-item.address-container p {
  margin: 0; 
  text-align: left;
}
.footer-item p {

  text-align: center;
}
.add{
text-align: center;
}

.close {
display: block;
text-align: right;
font-size: 2rem;
color: #333;
cursor: pointer;
}

footer {
  background: #32612D;
  padding: 1rem;
  text-align: center;
  margin-top: auto;
}


.footer-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
}

.footer-item {
  margin: 1rem 2rem;
}

footer p {
color: #fff;
margin-bottom: 1rem;
}

footer ul {
list-style: none;
}

footer ul li {
display: inline;
margin: 0.5rem;
}

footer ul li a {
text-decoration: none;
color: #fff;
}

@media screen and (max-width: 768px) {
.special-offers-container {
flex-direction: column;
}
}

@media screen and (max-width: 480px) {

h1 {
display: block;
margin-bottom: 1rem;
}
}

.footer-item iframe {
  width: 100%;
  height: 200px;
}

.footer-item form {
   display: inline-flex;
   align-items: center;
}
.footer-item input[type="email"] {
   padding: 0.5rem;
   border: none;
   border-radius: 5px;
   margin-right: 0.5rem;
}
.footer-item button {
   background-color: #ADC3AB;
   color: #32612D;
   padding: 0.5rem;
   border: none;
   border-radius: 5px;
   cursor: pointer;
}
.footer-item button:hover {
   background-color: #32612D;
   color: #fff;
}
.social-links-container {
  order: 2;
}


.address-container {
  order: 1;

}

.google-maps-container {
  order: 0;
