 {'content': 'using System;
using System.Net.Http;
using System.Web.Http;
using Microsoft.Xrm.Sdk;
using Microsoft.Xrm.Sdk.Client;
using Microsoft.Xrm.Sdk.Query;

namespace ProspectGeneration_API.Controllers
{
    public class DefaultController : ApiController
    {
        private IOrganizationService _service;
        private Guid _accountId;

        [Route("api/main")]
        [HttpPost]
        public HttpResponseMessage CreateProspect([FromBody] ProspectData data)
        {
            try
            {
                InitializeService();

                Entity prospect = new Entity("alfa_prospect");

                prospect["alfa_name"] = data.CompanyNameEN;
                prospect["alfa_businessenglishname"] = data.CompanyNameEN;
                prospect["alfa_businessarabicname"] = data.CompanyNameAR;
                prospect["alfa_postalcode"] = data.ZipCode;
                prospect["alfa_building"] = data.BuildingNumber;
                prospect["alfa_additionalnumber"] = data.AdditionalNumber;
                prospect["alfa_unitnumber"] = data.UnitNumber;
                prospect["alfa_shortaddress"] = data.ShortAddress;
                prospect["alfa_businessphone"] = data.BusinessPhoneNumber;
                prospect["alfa_contactfirstname"] = GetFirstName(data.FullName);
                prospect["alfa_contactlastname"] = GetLastName(data.FullName);
                prospect["alfa_contactphonenumber"] = data.PhoneNumber;
                prospect["alfa_contactemail"] = data.Email;
                prospect["alfa_crnumber"] = data.CRNumber;
                prospect["alfa_taxnumber"] = data.TaxNumber;
                prospect["alfa_accounttype"] = new OptionSetValue((int)data.AccountType);

                Guid prospectId = _service.Create(prospect);

                QualifyProspect(prospectId);

                return Request.CreateResponse(System.Net.HttpStatusCode.OK, _accountId);
            }
            catch (Exception)
            {
                return Request.CreateErrorResponse(System.Net.HttpStatusCode.InternalServerError, "An error occurred while creating prospect.");
            }
        }

        private void InitializeService()
        {
            Uri organizationUri = new Uri(Classes.Creds.WebserviceURL);
            Uri homeRealmUri = null;
            ClientCredentials clientCredentials = new ClientCredentials();
            clientCredentials.UserName.UserName = Classes.Creds.UserName;
            clientCredentials.UserName.Password = Classes.Creds.Password;

            _service = new OrganizationServiceProxy(organizationUri, homeRealmUri, clientCredentials, null);
            _service.EnableProxyTypes();
        }

        private void QualifyProspect(Guid prospectId)
        {
            EntityReference prospectRef = new EntityReference("alfa_prospect", prospectId);

            // Create input parameter object for qualifying the lead.
            QualifyLeadRequest qualifyRequest = new QualifyLeadRequest
            {
                CreateAccount = true,
                CreateContact = true,
                CreateOpportunity = false,
                Status = new OptionSetValue((int)lead_statuscode.Qualified),
                LeadId = prospectRef
            };

            QualifyLeadResponse qualifyResponse = (QualifyLeadResponse)_service.Execute(qualifyRequest);

            EntityReference accountRef = qualifyResponse.CreatedEntities.FirstOrDefault(e => e.LogicalName == "account")?.ToEntityReference();

            if (accountRef != null)
            {
                _accountId = accountRef.Id;
            }
        }

        private string GetFirstName(string fullName)
        {
            string[] nameParts = fullName.Split(' ');

            if (nameParts.Length > 0)
            {
                return nameParts[0];
            }

            return string.Empty;
        }

        private string GetLastName(string fullName)
        {
            string[] nameParts = fullName.Split(' ');

            if (nameParts.Length > 1)
            {
                return nameParts[nameParts.Length - 1];
            }

            return string.Empty;
        }
    }

    public class ProspectData
    {
        public string CompanyNameAR { get; set; }

        public string CompanyNameEN { get; set; }

        public string FullName { get; set; }

        public string Email { get; set; }

        public string PhoneNumber { get; set; }

        public AccountType AccountType { get; set; }

        public string CRNumber { get; set; }

        public string TaxNumber { get; set; }

        public string BusinessPhoneNumber { get; set; }

        public string ShortAddress { get; set; }

        public string BuildingNumber { get; set; }

        public string AdditionalNumber { get; set; }

        public string ZipCode { get; set; }
    }

    public enum AccountType
    {
        Type1 = 1,
        Type2 = 2,
        Type3 = 3
    }
