                        return jsonify({'success':'OTP sent successfully'})
                    else:
                        # If the number does not exist, return false
                        return jsonify({'error': 'Mobile number not registered'})
                else:
                    return jsonify({'error': 'Invalid mobile number'})
            else:
                return jsonify({'error': 'JSON not available'})
        else:
            return jsonify({'error': 'Method is not allowed'})
    except Exception as identifier:
        # Assuming Logger is defined elsewhere in your code
        Logger.error(identifier)  # Replace with your logging mechanism
    finally:
        session.close()


