@Register_Blueprint.route('/verifyOTP', methods=['POST'])
def verify_otp():
    session = Session()
    try:
        request_json = request.get_json()
        if request_json:
            Mobile = request_json.get('mobile')
            otp_code = request_json.get('otp_code')  # This should be the code the user received

