  if(font){
    return (
      <SafeAreaView style={{ flex: 1 }}>
      <Navigation/>
      </SafeAreaView>
    );
  }else{
    return(
      <AppLoading startAsync={fonts} onFinish={()=>setFont(true)} onError={console.warn}/>
    )
  }

};
